-- Spec #20 review, finding A: one sport vocabulary (app/domain/sports.ts).
-- Stored sport names become the canonical Olympic programme names.
-- World Aquatics competitions are one row per sport now (source ref "<id>/<code>"):
-- an existing "Aquatics" row becomes the swimming row. UCI rows take the sport of
-- their discipline (source ref "<discipline id>/<competition id>").
UPDATE `competition` SET `source_ref` = `source_ref` || '/SW', `sport` = 'Swimming' WHERE `source` = 'world-aquatics' AND lower(`sport`) = 'aquatics' AND `source_ref` NOT LIKE '%/%';
--> statement-breakpoint
UPDATE `competition` SET `sport` = CASE substr(`source_ref`, 1, instr(`source_ref`, '/') - 1) WHEN '10' THEN 'Cycling road' WHEN '9' THEN 'Cycling track' WHEN '7' THEN 'Cycling mountain bike' WHEN '1' THEN 'Cycling BMX racing' WHEN '13' THEN 'Cycling BMX freestyle' ELSE `sport` END WHERE `source` = 'uci-cycling' AND lower(`sport`) = 'cycling';
--> statement-breakpoint
-- Aquatics Teams and Entries by their event: synchro diving, artistic swimming, the rest swimming.
UPDATE OR IGNORE `team` SET `sport` = CASE WHEN lower(`event`) LIKE '%synchro%' OR lower(`event`) LIKE '%diving%' OR lower(`event`) LIKE '%springboard%' OR lower(`event`) LIKE '%platform%' THEN 'Diving' WHEN lower(`event`) LIKE '%duet%' OR lower(`event`) LIKE '%acrobatic%' OR lower(`event`) LIKE '%artistic%' THEN 'Artistic swimming' WHEN lower(`event`) LIKE '%water polo%' THEN 'Water polo' WHEN lower(`event`) LIKE '%open water%' OR lower(`event`) LIKE '%10km%' THEN 'Marathon swimming' ELSE 'Swimming' END WHERE lower(`sport`) = 'aquatics';
--> statement-breakpoint
UPDATE OR IGNORE `entry` SET `sport` = CASE WHEN lower(`event`) LIKE '%synchro%' OR lower(`event`) LIKE '%diving%' OR lower(`event`) LIKE '%springboard%' OR lower(`event`) LIKE '%platform%' THEN 'Diving' WHEN lower(`event`) LIKE '%duet%' OR lower(`event`) LIKE '%acrobatic%' OR lower(`event`) LIKE '%artistic%' THEN 'Artistic swimming' WHEN lower(`event`) LIKE '%water polo%' THEN 'Water polo' WHEN lower(`event`) LIKE '%open water%' OR lower(`event`) LIKE '%10km%' THEN 'Marathon swimming' ELSE 'Swimming' END WHERE lower(`sport`) = 'aquatics';
--> statement-breakpoint
UPDATE OR IGNORE `quota_place` SET `sport` = CASE WHEN lower(`event`) LIKE '%synchro%' OR lower(`event`) LIKE '%diving%' OR lower(`event`) LIKE '%springboard%' OR lower(`event`) LIKE '%platform%' THEN 'Diving' WHEN lower(`event`) LIKE '%duet%' OR lower(`event`) LIKE '%acrobatic%' OR lower(`event`) LIKE '%artistic%' THEN 'Artistic swimming' WHEN lower(`event`) LIKE '%water polo%' THEN 'Water polo' WHEN lower(`event`) LIKE '%open water%' OR lower(`event`) LIKE '%10km%' THEN 'Marathon swimming' ELSE 'Swimming' END WHERE lower(`sport`) = 'aquatics';
--> statement-breakpoint
UPDATE OR IGNORE `team` SET `sport` = 'Cycling track' WHERE lower(`sport`) = 'cycling';
